qss:
/* ===== PS01-PAPER 结构观感（v3.42.0，随深浅主题=夜灯纸）===== */
/* chrome 全衬线斜体（用斜体区分「界面」与「内容」）*/
QMenuBar::item, QStatusBar, QMainWindow #tabstrip QTabBar::tab,
QToolBar#sideTB QToolButton {
  font-family: Georgia, "Times New Roman", "SimSun", serif;
  font-style: italic;
}
QMenu { font-family: Georgia, "Times New Roman", "SimSun", serif; }
/* 直角裁切：窗口控件一律小圆角/直角 */
QToolButton, QMenu, QLineEdit, QComboBox, QPushButton {
  border-radius: 2px;
}
QMainWindow #tabstrip QTabBar::tab:!selected {
  border-radius: 2px 2px 0 0;
  border: 1px solid transparent;
}
QMainWindow #tabstrip QTabBar::tab:selected {
  border-color: {border};
  border-bottom: none;
}
QMenu::item:selected {
  background: {menu_hover_bg};
  color: {accent};
}

editor_css:
/* 纸张：书桌底 + 居中纸面 + 朱砂顶线（v3.42.0）*/
body { background: {desk} !important; }
#editor {
  max-width: 760px;
  margin: 18px auto 60px auto;
  background: {paper_bg};
  box-shadow: 0 3px 14px rgba(80,65,40,.25);
  border-top: 3px solid {accent};
  box-sizing: border-box;
}

editor_css_dark:
/* 夜灯纸：暖深褐底（非纯黑）*/
body { background: {desk} !important; }
#editor {
  max-width: 760px;
  margin: 18px auto 60px auto;
  background: {paper_bg};
  box-shadow: 0 3px 14px rgba(0,0,0,.5);
  border-top: 3px solid {accent};
  box-sizing: border-box;
}
